#include <bits/stdc++.h>
#include <atcoder/segtree>

using namespace std;

using ll = long long;

const ll inf = 1LL << 60;

const int SZ = 4;
using S = array<pair<ll, ll>, SZ>;

S op(const S &a, const S &b) {
    array<pair<ll, ll>, SZ * 2> c;
    copy(a.begin(), a.end(), c.begin());
    copy(b.begin(), b.end(), c.begin() + SZ);
    sort(c.rbegin(), c.rend());
    S res;
    int it = 0;
    for (int i = 0; i < SZ; i++) {
        while (true) {
            bool ok = true;
            for (int j = 0; j < i; j++) {
                if (res[j].second == c[it].second) {
                    ok = false;
                    break;
                }
            }
            if (ok) break;
            it++;
        }
        res[i] = c[it++];
    }
    return res;
}

S e() {
    return {
            make_pair(-inf, -1),
            make_pair(-inf, -2),
            make_pair(-inf, -3),
            make_pair(-inf, -4)
    };
}

S single(ll k, ll a) {
    a = max(a, -inf);
    S res = e();
    res[0] = {a, k};
    return res;
}

S add(S s, ll k, ll a) {
    for (int i = 0; i < SZ; i++) {
        if (s[i].second == k) {
            s[i].first = max(s[i].first, a);
            sort(s.rbegin(), s.rend());
            return s;
        }
    }
    array<pair<ll, ll>, SZ + 1> tmp;
    copy(s.begin(), s.end(), tmp.begin());
    tmp[SZ] = {a, k};
    sort(tmp.rbegin(), tmp.rend());
    for (int i = 0; i < SZ; i++) {
        s[i] = tmp[i];
    }
    return s;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<ll> k(n), a(n);
    vector<vector<int>> ls(n);
    for (int i = 0; i < n; i++) {
        cin >> k[i] >> a[i];
        --k[i];
        ls[k[i]].push_back(i);
    }

    vector<S> l(n + 1), r(n + 1);
    l[0] = r[n] = e();
    for (int i = 0; i < n; i++) {
        l[i + 1] = add(l[i], k[i], a[i]);
    }
    for (int i = n - 1; i >= 0; i--) {
        r[i] = add(r[i + 1], k[i], a[i]);
    }

    vector<ll> ori(n);
    vector<S> init(n);
    vector<vector<pair<int, ll>>> change(n);
    for (int i = 0; i < n; i++) {
        vector<pair<ll, ll>> cand;
        for (auto p: l[i]) {
            if (p.second != k[i]) cand.push_back(p);
        }
        assert(cand.size() >= 3);
        ori[i] = a[i] + cand[0].first + cand[1].first;
        init[i] = single(k[i], ori[i]);
        for (int j = 0; j < 2; j++) {
            if (cand[j].second < 0) continue;
            ll now = ori[i] - cand[j].first + cand[2].first;
            change[cand[j].second].emplace_back(i, now);
        }
    }

    atcoder::segtree<S, op, e> st(init);
    ll ans = -1;
    for (int c = 0; c < n; c++) {
        for (auto [i, now]: change[c]) {
            st.set(i, single(k[i], now));
        }
        for (int i: ls[c]) {
            vector<pair<ll, ll>> cand;
            for (auto p: r[i + 1]) {
                if (p.second != k[i]) cand.push_back(p);
            }
            assert(cand.size() >= 3);
            S best = st.prod(0, i);
            for (auto p: best) {
                if (p.second == k[i]) continue;
                ll now;
                if (p.second == cand[0].second) {
                    now = cand[1].first + cand[2].first;
                } else if (p.second == cand[1].second) {
                    now = cand[0].first + cand[2].first;
                } else {
                    now = cand[0].first + cand[1].first;
                }
                now += p.first + a[i];
                ans = max(ans, now);
            }
        }
        for (auto [i, _]: change[c]) {
            st.set(i, single(k[i], ori[i]));
        }
    }

    cout << ans << endl;
}
